def test_a_warehouse_plugin_adds_audit_and_apply_tasks_that_run_through_the_connection(
    jaffle_repo: Path, monkeypatch: pytest.MonkeyPatch
):
    register(monkeypatch, "warehouse", "fake", FakeWarehouse)
    (jaffle_repo / "datapatchbay.yaml").write_text("schema_version: 1\nwarehouse: fake\nconnection: dwh\n")
    generate_repo(jaffle_repo)
    text = generated(jaffle_repo, "sa_jaffle_orders.py")
    assert "from airflow.providers.common.sql.operators.sql import SQLExecuteQueryOperator\n" in text
    body = text[text.index("with DAG(") :]
    assert body.split("tags=")[1] == (
        '["datapatchbay"],\n'
        "):\n"
        '    build_ingested_orders = _build_task("build_ingested_orders", "src/ingested.py", "build", {"limit": 100})\n'
        "    audit_ingested_orders = SQLExecuteQueryOperator(\n"
        '        task_id="audit_ingested_orders",\n'
        '        conn_id="dwh",\n'
        "        sql=\"SELECT 'it''s' FROM ingested_orders WHERE false\",\n"
        "    )\n"
        "    build_ingested_orders >> audit_ingested_orders\n"
        '    build_orders = _build_task("build_orders", "src/orders.py", "build", {})\n'
        "    audit_orders = SQLExecuteQueryOperator(\n"
        '        task_id="audit_orders",\n'
        '        conn_id="dwh",\n'
        "        sql=\"SELECT 'it''s' FROM orders WHERE false\",\n"
        "    )\n"
        "    build_orders >> audit_orders\n"
        "    audit_ingested_orders >> build_orders\n"
        "    apply_grants = SQLExecuteQueryOperator(\n"
        '        task_id="apply_grants",\n'
        '        conn_id="dwh",\n'
        '        sql="GRANT USAGE ON SCHEMA sa_jaffle_orders TO reader;",\n'
        "    )\n"
        "    audit_orders >> apply_grants\n"
        "\n"
        '    @task(task_id="publish_outputs", outlets=[Asset(name="sa_jaffle_orders", uri="x-datapatchbay://sa_jaffle_orders")])\n'
        "    def publish_outputs():\n"
        '        """Mark the output ports as updated; Airflow does so when this task succeeds."""\n'
        "\n"
        "    publish = publish_outputs()\n"
        "    apply_grants >> publish\n"
    )


def test_the_postgres_warehouse_ends_each_dag_with_a_task_that_applies_the_access_through_the_connection(
    jaffle_repo: Path,
):
    (jaffle_repo / "datapatchbay.yaml").write_text("schema_version: 1\nconnection: dwh\n")
    generate_repo(jaffle_repo)
    body = generated(jaffle_repo, "sa_jaffle_orders.py")
    body = body[body.index("with DAG(") :]
    assert (
        '        task_id="apply_access",\n        conn_id="dwh",\n        sql="-- Output port sa_jaffle_orders\\n'
        in body
    )
    assert body.index("apply_access") < body.index("publish_outputs")
    assert "    build_orders >> audit_orders\n" in body
    assert "    audit_orders >> apply_access\n" in body
    assert "    apply_access >> publish\n" in body
    assert '    audit_orders = _audit_task("audit_orders", "dwh", [{"rule": "row_count", "table": "orders"' in body
    assert body.endswith("    apply_access >> publish\n")


def test_docker_and_kubernetes_tables_sit_in_one_dag_with_other_runtimes(jaffle_repo: Path):
    ingested = jaffle_repo / "dataproducts/sa_jaffle_orders/inputs/sa_jaffle_orders_private/ingested.yaml"
    ingested.write_text(ingested.read_text().replace("build:\n", "build:\n  runtime: docker\n  image: jaffle-shop:1\n"))
    orders = jaffle_repo / "dataproducts/sa_jaffle_orders/outputs/sa_jaffle_orders/orders.yaml"
    orders.write_text(
        orders.read_text().replace(
            "build:\n", "build:\n  runtime: kubernetes\n  image: jaffle-shop:2\n  container: {namespace: data}\n"
        )
    )
    generate_repo(jaffle_repo)
    dag = (jaffle_repo / "generated/sa_jaffle_orders.py").read_text()
    assert "build_ingested_orders = DockerOperator(" in dag
    assert "build_orders = KubernetesPodOperator(" in dag
    assert 'namespace="data"' in dag
    assert "build_ingested_orders >> build_orders" in dag


def test_the_dbt_tables_of_a_data_product_build_in_one_dbt_build_task_after_its_python_tables(jaffle_dbt_repo: Path):
    generate_repo(jaffle_dbt_repo)
    dag = generated(jaffle_dbt_repo, "agg_weekly_orders.py")
    assert dag.count("_dbt_build_task(") == 2  # the helper and the one task
    assert (
        '    build_dbt = _dbt_build_task("build_dbt", "../..", "~/.dbt", "dataproducts/agg_weekly_orders/models")\n'
        in dag
    )
    assert "    build_weekly_pod >> build_dbt\n" in dag
    assert "    build_dbt >> apply_access\n" in dag
    assert "build_weekly_summary" not in dag
    assert "audit_weekly_summary" not in dag
    assert "    build_weekly_pod >> apply_access\n" not in dag


