def test_a_failed_write_is_a_generation_error_and_leaves_no_temporary_file(
    jaffle_repo: Path, monkeypatch: pytest.MonkeyPatch
):
    def refuse(src: object, dst: object) -> None:
        raise PermissionError(13, "Permission denied")

    monkeypatch.setattr("os.replace", refuse)
    with pytest.raises(GenerationError, match=r"cannot write .*Permission denied"):
        generate_repo(jaffle_repo)
    assert [path.name for path in (jaffle_repo / "generated").iterdir()] == []


def test_a_file_is_replaced_whole_so_an_older_one_stays_until_the_new_one_is_ready(jaffle_repo: Path):
    generate_repo(jaffle_repo)
    before = (jaffle_repo / "generated/sa_jaffle_orders.py").read_text()
    generate_repo(jaffle_repo)
    assert (jaffle_repo / "generated/sa_jaffle_orders.py").read_text() == before
    assert not [path for path in (jaffle_repo / "generated").iterdir() if path.name.startswith(".")]


STALE = (
    "# Generated by datapatchbay from dataproducts/gone/dataproduct.yaml. "
    "Do not edit: `dpb generate` overwrites this file.\n"
)


def test_validate_flags_a_generated_file_whose_data_product_is_gone(jaffle_repo: Path):
    generate_repo(jaffle_repo)
    assert validate_repo(jaffle_repo).problems == []
    (jaffle_repo / "generated/gone.py").write_text(STALE + "x = 1\n")
    [problem] = validate_repo(jaffle_repo).problems
    assert problem.file.as_posix() == "generated/gone.py"
    assert "dataproducts/gone/dataproduct.yaml" in problem.message
    assert "delete it" in problem.message


def test_validate_leaves_hand_written_files_in_the_output_folder_alone(jaffle_repo: Path):
    (jaffle_repo / "generated").mkdir()
    (jaffle_repo / "generated/helper.py").write_text("x = 1\n")
    (jaffle_repo / "generated/notes.txt").write_bytes(b"\xff\xfe")
    assert validate_repo(jaffle_repo).problems == []


def test_generate_does_not_delete_a_stale_dag_file(jaffle_repo: Path):
    (jaffle_repo / "generated").mkdir()
    (jaffle_repo / "generated/gone.py").write_text(STALE)
    assert generate_repo(jaffle_repo).report.ok
    assert (jaffle_repo / "generated/gone.py").exists()
